// The second polygon: a synthetic upstream with no product model at all
// (FEAT-001 ##POLYGON-GENERIC-IS-SYNTHETIC, PROP-016 ##TYPE-GENERIC).
//
// It is a small git repository generated by code - no product manifest, no
// extension directory, no service registry, no entry module - and it is the
// standing proof that the engine works over anything a fork tree can be. Its
// only manifest is an ordinary `app.json`, which the patch set names as its
// overlay target and as the fingerprint of a healthy tree; its build, lint and
// test commands are stub scripts the patch set declares in `typeConfig`.
//
// The history is the shape an upgrade has to survive between two pins:
//
//   c1 (anchor, root)                    the commit ##ID-CHECK-ORIGIN looks for
//   c2  a settings module        -> v1.0.0   "old pin"
//   c3  edit in panel.ts, away from the hook  drift the patch must not collide with
//   c4  edit in util.ts + legacy.ts deleted -> v1.1.0  "new pin"
//
// Everything is deterministic: fixed author, fixed committer, fixed dates one
// minute apart, so the commit shas are identical on every machine and run.

import { chmodSync, mkdirSync } from 'node:fs';
import { fixtureCommit, fixtureGit } from './makeUpstream.ts';
import type { UpstreamRef } from './makeUpstream.ts';
import { writeBytes } from './patchText.ts';

export type GenericUpstreamFixture = {
	/** Absolute path of the generated work tree. */
	readonly dir: string;
	/** Root commit: what PROP-008 ##ID-CHECK-ORIGIN checks for. */
	readonly anchorSha: string;
	readonly v1: UpstreamRef;
	readonly v2: UpstreamRef;
};

/** The JSON manifest: the overlay target and the fingerprint of the tree. */
export const APP_MANIFEST_PATH = 'app.json';
/** Target of the sample patch and of the sample rewrite rule. */
export const PANEL_PATH = 'src/panel.ts';
/** Exact line the sample patch hooks after. */
export const PANEL_RENDER_ANCHOR = '\tstatic render(area: string): string[] {';
/** Exact line the sample rewrite rule matches. */
export const PANEL_TOOLBAR_ANCHOR = '\tstatic toolbar(area: string): string[] {';
/** Edited between the two pins, away from anything the patch set owns. */
export const UTIL_PATH = 'src/util.ts';
/** Deleted between the two pins: the target-deleted case of the classifier. */
export const LEGACY_PATH = 'src/legacy.ts';
/** The binary the resource-file layer replaces. */
export const LOGO_PATH = 'assets/logo.bin';

const FIRST_COMMIT_ISO = '2026-03-01T00:00:00Z';

/**
 * Generate the fixture into `dir` (created if absent, expected to be empty).
 * Returns the anchor and both pins.
 */
export function makeGenericUpstream(dir: string): GenericUpstreamFixture {
	mkdirSync(dir, { recursive: true });
	fixtureGit(dir, ['init', '--quiet', '--initial-branch=main', '.']);

	let clock = 0;
	writeAll(dir, rootFiles());
	const anchorSha = fixtureCommit(dir, 'fixture: initial plain upstream', commitDate(clock));
	clock += 1;

	writeAll(dir, new Map([['src/settings.ts', SETTINGS_TS]]));
	const v1Date = commitDate(clock);
	const v1Sha = fixtureCommit(dir, 'fixture: settings module', v1Date);
	fixtureGit(dir, ['tag', 'v1.0.0']);
	clock += 1;

	// c3: an edit far away from where the patch lands.
	writeBytes(`${dir}/${PANEL_PATH}`, panelAfterHeaderEdit());
	fixtureCommit(dir, 'fixture: name the panel in its header', commitDate(clock));
	clock += 1;

	// c4: an unrelated module changes and an obsolete one is deleted.
	writeBytes(`${dir}/${UTIL_PATH}`, UTIL_TS_V2);
	fixtureGit(dir, ['rm', '--quiet', LEGACY_PATH]);
	const v2Date = commitDate(clock);
	const v2Sha = fixtureCommit(dir, 'fixture: widen join and drop the legacy module', v2Date);
	fixtureGit(dir, ['tag', 'v1.1.0']);

	return {
		dir,
		anchorSha,
		v1: { tag: 'v1.0.0', sha: v1Sha, dateIso: v1Date },
		v2: { tag: 'v1.1.0', sha: v2Sha, dateIso: v2Date }
	};
}

function commitDate(minute: number): string {
	return new Date(Date.parse(FIRST_COMMIT_ISO) + minute * 60_000).toISOString().replace('.000Z', 'Z');
}

function writeAll(dir: string, files: ReadonlyMap<string, string | Uint8Array>): void {
	for (const [relative, content] of files) {
		writeBytes(`${dir}/${relative}`, content);
		if (relative.endsWith('.mjs')) {
			chmodSync(`${dir}/${relative}`, 0o755);
		}
	}
}

function rootFiles(): ReadonlyMap<string, string | Uint8Array> {
	return new Map<string, string | Uint8Array>([
		['.gitignore', GITIGNORE],
		['README.md', README],
		['package.json', PACKAGE_JSON],
		[APP_MANIFEST_PATH, APP_JSON],
		['build/check.mjs', CHECK_MJS],
		[PANEL_PATH, PANEL_TS],
		[UTIL_PATH, UTIL_TS],
		[LEGACY_PATH, LEGACY_TS],
		[LOGO_PATH, new Uint8Array([0x01, 0x02, 0x03, 0x04, 0x7f, 0x80, 0xfe, 0xff, 0x00, 0x10, 0x20, 0x30])]
	]);
}

const GITIGNORE = `node_modules/
build/out/
`;

const README = `# fixture-app

A plain git upstream with no product model: no extension host, no service
registry, no entry module. It exists so that Codkit can be proved over a
repository that is nothing but a repository.
`;

const PACKAGE_JSON = `{
	"name": "fixture-app",
	"version": "1.0.0",
	"private": true,
	"scripts": {
		"lint": "node build/check.mjs lint",
		"typecheck": "node build/check.mjs typecheck",
		"test": "node build/check.mjs own-tests"
	}
}
`;

/**
 * The manifest of the fixture upstream: an ordinary JSON document. Nothing in
 * the tool knows what any of these keys mean - the patch set declares the file
 * as its overlay target and the type carries the declaration.
 */
const APP_JSON = `{
	"name": "fixture-app",
	"displayName": "Fixture App",
	"channel": "stable",
	"features": {
		"panel": true
	}
}
`;

/**
 * The fixture counterpart of an upstream's own lint and test runners. It
 * asserts the ordering PROP-011 fixes: lint sees the manifest as the pin left
 * it, and the own tests see the overlay materialized and receive the glob of
 * the own root.
 */
const CHECK_MJS = `#!/usr/bin/env node
import { appendFileSync, mkdirSync, readFileSync } from 'node:fs';

const step = process.argv[2];
const manifest = JSON.parse(readFileSync('app.json', 'utf8'));
mkdirSync('build/out', { recursive: true });
appendFileSync('build/out/steps.log', step + '\\n', 'utf8');

if (step === 'lint' || step === 'typecheck') {
	if (manifest.displayName !== 'Fixture App' || Object.hasOwn(manifest, 'patchsetPin')) {
		console.error(step + ': the overlay target was materialized before the upstream gates');
		process.exit(1);
	}
	if (process.env.STUB_LINT_MODE === 'fail') {
		console.error(step + ': fixture check failed');
		process.exit(1);
	}
	console.log(step + ': fixture check passed before overlay materialization');
	process.exit(0);
}

if (step === 'own-tests') {
	const glob = process.argv[3];
	if (glob !== 'src/own/**/*.test.*') {
		console.error('own-tests: expected the own-root glob, got ' + String(glob));
		process.exit(1);
	}
	if (manifest.displayName !== 'Fixture PatchSet' || typeof manifest.patchsetPin !== 'string') {
		console.error('own-tests: the overlay target was not materialized before the tests');
		process.exit(1);
	}
	if (process.env.STUB_TEST_MODE === 'fail') {
		console.error('own-tests: fixture tests failed');
		process.exit(1);
	}
	console.log('own-tests: fixture tests passed over ' + glob);
	process.exit(0);
}

console.error('unknown step: ' + String(step));
process.exit(2);
`;

const PANEL_TS = `// The panel of the fixture upstream.

import { join } from './util.js';

export class Panel {
	static render(area: string): string[] {
		return [join('panel', area)];
	}

	static toolbar(area: string): string[] {
		return [join('toolbar', area)];
	}
}
`;

function panelAfterHeaderEdit(): string {
	return PANEL_TS.replace('// The panel of the fixture upstream.', '// The panel of the fixture upstream (the main one).');
}

const UTIL_TS = `// Small helpers of the fixture upstream.

export function join(kind: string, area: string): string {
	return kind + ':' + area;
}
`;

const UTIL_TS_V2 = `// Small helpers of the fixture upstream.

export function join(kind: string, area: string, suffix = ''): string {
	return suffix === '' ? kind + ':' + area : kind + ':' + area + ':' + suffix;
}
`;

const LEGACY_TS = `// Kept only until v1.1.0, then deleted upstream.

export const LEGACY = true;
`;

const SETTINGS_TS = `// Settings of the fixture upstream.

export const SETTINGS = new Set(['panel']);
`;
